use clap::Parser;
use std::collections::BTreeMap;
use std::fs;
use std::path::{Path, PathBuf};
use serde::{Deserialize, Serialize};
use std::io::Read;

mod language;
mod counter;
mod config;

use language::Language;
use counter::CountResult;

#[derive(Parser)]
#[command(name = "executable")]
#[command(about = "Count your code, quickly.")]
#[command(long_about = "Support this project on GitHub Sponsors: https://github.com/sponsors/XAMPPRocky")]
#[command(version = "14.0.0 compiled with serialization support: json")]
struct Args {
    /// The path(s) to the file or directory to be counted. (default current directory)
    #[arg(value_name = "input")]
    input: Vec<String>,

    /// Will print out statistics on individual files.
    #[arg(short = 'f', long)]
    files: bool,

    /// Prints out supported languages and their extensions.
    #[arg(short = 'l', long)]
    languages: bool,

    /// Prints version information
    #[arg(short = 'V', long)]
    version: bool,

    /// Sets a strict column width of the output, only available for terminal output.
    #[arg(short = 'c', long)]
    columns: Option<usize>,

    /// Ignore all files & directories matching the pattern.
    #[arg(short = 'e', long)]
    exclude: Vec<String>,

    /// Gives statistics from a previous tokei run. Can be given a file path, or "stdin" to read from stdin.
    #[arg(short = 'i', long)]
    input_file: Option<String>,

    /// Count hidden files.
    #[arg(long)]
    hidden: bool,

    /// Don't respect ignore files (.gitignore, .ignore, etc.). This implies --no-ignore-parent,
    /// --no-ignore-dot, and --no-ignore-vcs.
    #[arg(long)]
    no_ignore: bool,

    /// Don't respect .ignore and .tokeignore files, including those in parent directories.
    #[arg(long)]
    no_ignore_dot: bool,

    /// Don't respect ignore files (.gitignore, .ignore, etc.) in parent directories.
    #[arg(long)]
    no_ignore_parent: bool,

    /// Don't respect VCS ignore files (.gitignore, .hgignore, etc.) including those in parent directories.
    #[arg(long)]
    no_ignore_vcs: bool,

    /// Outputs Tokei in a specific format. Compile with additional features for more format support.
    #[arg(short = 'o', long)]
    output: Option<String>,

    /// Sort languages based on column
    #[arg(short = 's', long)]
    sort: Option<String>,

    /// Reverse sort languages based on column
    #[arg(short = 'r', long)]
    rsort: Option<String>,

    /// Filters output by language type, separated by a comma. i.e. -t=Rust,Markdown
    #[arg(short = 't', long)]
    types: Option<String>,

    /// Do not print statistics about embedded languages.
    #[arg(short = 'C', long)]
    compact: bool,

    /// Format of printed numbers, i.e., plain (1234, default), commas (1,234), dots (1.234), or underscores (1_234). Cannot be used with --output.
    #[arg(short = 'n', long)]
    num_format: Option<String>,

    /// prints the (language, path, lines, blanks, code, comments) records as simple lines or as Json for batch processing
    #[arg(long)]
    streaming: Option<String>,

    /// Set log output level
    #[arg(short = 'v', long, action = clap::ArgAction::Count)]
    verbose: u8,
}

fn main() {
    let args = Args::parse();

    if args.languages {
        print_languages();
        return;
    }

    let paths = if args.input.is_empty() {
        vec![".".to_string()]
    } else {
        args.input
    };

    let mut results = BTreeMap::new();

    for path_str in paths {
        let path = Path::new(&path_str);
        count_path(path, &mut results);
    }

    if args.output == Some("json".to_string()) {
        print_json(&results);
    } else {
        print_table(&results, args.files, args.num_format.as_deref());
    }
}

fn count_path(path: &Path, results: &mut BTreeMap<String, CountResult>) {
    if path.is_file() {
        if let Some(lang) = language::detect_language(path) {
            let counts = counter::count_file(path);
            results.entry(lang.name().to_string())
                .or_insert_with(|| CountResult::new())
                .merge(counts);
        }
    } else if path.is_dir() {
        count_directory(path, results);
    }
}

fn count_directory(dir: &Path, results: &mut BTreeMap<String, CountResult>) {
    if let Ok(entries) = fs::read_dir(dir) {
        for entry in entries {
            if let Ok(entry) = entry {
                let path = entry.path();
                if path.is_dir() {
                    count_directory(&path, results);
                } else if path.is_file() {
                    if let Some(lang) = language::detect_language(&path) {
                        let counts = counter::count_file(&path);
                        results.entry(lang.name().to_string())
                            .or_insert_with(|| CountResult::new())
                            .merge(counts);
                    }
                }
            }
        }
    }
}

fn print_languages() {
    let langs = language::get_all_languages();
    println!("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━");
    println!("┃ {:36} ┃ {:30} ┃", "Language", "Extensions");
    println!("┃━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┃");
    for lang in langs {
        let exts = lang.extensions().join(", ");
        println!("┃ {:36} ┃ {:30} ┃", lang.name(), exts);
    }
    println!("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━");
}

fn print_table(results: &BTreeMap<String, CountResult>, files: bool, num_format: Option<&str>) {
    let mut total_lines = 0;
    let mut total_code = 0;
    let mut total_comments = 0;
    let mut total_blanks = 0;
    let mut total_files = 0;

    for (_, result) in results {
        total_files += result.files;
        total_lines += result.lines;
        total_code += result.code;
        total_comments += result.comments;
        total_blanks += result.blanks;
    }

    println!("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━");
    println!(" {:18} {:12} {:13} {:12} {:15} {:12}", 
             "Language", "Files", "Lines", "Code", "Comments", "Blanks");
    println!("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━");

    for (lang, result) in results {
        let fmt = num_format.unwrap_or("plain");
        println!(" {:18} {:12} {:13} {:12} {:15} {:12}",
                 lang,
                 format_number(result.files, fmt),
                 format_number(result.lines, fmt),
                 format_number(result.code, fmt),
                 format_number(result.comments, fmt),
                 format_number(result.blanks, fmt));
    }

    println!("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━");
    println!(" {:18} {:12} {:13} {:12} {:15} {:12}",
             "Total",
             format_number(total_files, num_format.unwrap_or("plain")),
             format_number(total_lines, num_format.unwrap_or("plain")),
             format_number(total_code, num_format.unwrap_or("plain")),
             format_number(total_comments, num_format.unwrap_or("plain")),
             format_number(total_blanks, num_format.unwrap_or("plain")));
    println!("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━");
}

fn format_number(n: usize, format: &str) -> String {
    match format {
        "commas" => {
            let s = n.to_string();
            let mut result = String::new();
            for (i, c) in s.chars().rev().enumerate() {
                if i > 0 && i % 3 == 0 {
                    result.push(',');
                }
                result.push(c);
            }
            result.chars().rev().collect()
        },
        "dots" => {
            let s = n.to_string();
            let mut result = String::new();
            for (i, c) in s.chars().rev().enumerate() {
                if i > 0 && i % 3 == 0 {
                    result.push('.');
                }
                result.push(c);
            }
            result.chars().rev().collect()
        },
        "underscores" => {
            let s = n.to_string();
            let mut result = String::new();
            for (i, c) in s.chars().rev().enumerate() {
                if i > 0 && i % 3 == 0 {
                    result.push('_');
                }
                result.push(c);
            }
            result.chars().rev().collect()
        },
        _ => n.to_string(),
    }
}

fn print_json(results: &BTreeMap<String, CountResult>) {
    // Simple JSON output
    let mut json_map = serde_json::json!({});

    for (lang, result) in results {
        json_map[lang] = serde_json::json!({
            "blanks": result.blanks,
            "code": result.code,
            "comments": result.comments,
            "lines": result.lines,
            "files": result.files
        });
    }

    println!("{}", serde_json::to_string(&json_map).unwrap());
}
