#[derive(Debug)]
struct Args {
    input: Vec<String>,
    files: bool,
    languages: bool,
    version: bool,
    columns: Option<usize>,
    exclude: Vec<String>,
    input_file: Option<String>,
    hidden: bool,
    no_ignore: bool,
    no_ignore_dot: bool,
    no_ignore_parent: bool,
    no_ignore_vcs: bool,
    output: Option<String>,
    sort: Option<String>,
    rsort: Option<String>,
    types: Option<String>,
    compact: bool,
    num_format: Option<String>,
    streaming: Option<String>,
    verbose: u8,
}

impl Default for Args {
    fn default() -> Self {
        Args {
            input: Vec::new(),
            files: false,
            languages: false,
            version: false,
            columns: None,
            exclude: Vec::new(),
            input_file: None,
            hidden: false,
            no_ignore: false,
            no_ignore_dot: false,
            no_ignore_parent: false,
            no_ignore_vcs: false,
            output: None,
            sort: None,
            rsort: None,
            types: None,
            compact: false,
            num_format: None,
            streaming: None,
            verbose: 0,
        }
    }
}

fn parse_args() -> Args {
    let args: Vec<String> = env::args().collect();
    let mut parsed = Args::default();

    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "--version" | "-V" => {
                parsed.version = true;
            }
            "--files" | "-f" => {
                parsed.files = true;
            }
            "--languages" | "-l" => {
                parsed.languages = true;
            }
            "--columns" | "-c" => {
                if i + 1 < args.len() {
                    i += 1;
                    parsed.columns = args[i].parse().ok();
                }
            }
            "--exclude" | "-e" => {
                if i + 1 < args.len() {
                    i += 1;
                    parsed.exclude.push(args[i].clone());
                }
            }
            "--input" | "-i" => {
                if i + 1 < args.len() {
                    i += 1;
                    parsed.input_file = Some(args[i].clone());
                }
            }
            "--hidden" => {
                parsed.hidden = true;
            }
            "--no-ignore" => {
                parsed.no_ignore = true;
            }
            "--no-ignore-dot" => {
                parsed.no_ignore_dot = true;
            }
            "--no-ignore-parent" => {
                parsed.no_ignore_parent = true;
            }
            "--no-ignore-vcs" => {
                parsed.no_ignore_vcs = true;
            }
            "--output" | "-o" => {
                if i + 1 < args.len() {
                    i += 1;
                    parsed.output = Some(args[i].clone());
                }
            }
            "--sort" | "-s" => {
                if i + 1 < args.len() {
                    i += 1;
                    parsed.sort = Some(args[i].clone());
                }
            }
            "--rsort" | "-r" => {
                if i + 1 < args.len() {
                    i += 1;
                    parsed.rsort = Some(args[i].clone());
                }
            }
            "--types" | "-t" => {
                if i + 1 < args.len() {
                    i += 1;
                    parsed.types = Some(args[i].clone());
                }
            }
            "--compact" | "-C" => {
                parsed.compact = true;
            }
            "--num-format" | "-n" => {
                if i + 1 < args.len() {
                    i += 1;
                    parsed.num_format = Some(args[i].clone());
                }
            }
            "--streaming" => {
                if i + 1 < args.len() {
                    i += 1;
                    parsed.streaming = Some(args[i].clone());
                }
            }
            "--verbose" | "-v" => {
                parsed.verbose += 1;
            }
            "--help" | "-h" => {
                print_help();
                std::process::exit(0);
            }
            arg if arg.starts_with('-') => {
                eprintln!("Unknown option: {}", arg);
            }
            _ => {
                parsed.input.push(args[i].clone());
            }
        }
        i += 1;
    }

    parsed
}

fn print_help() {
    println!("Count your code, quickly.");
    println!("Support this project on GitHub Sponsors: https://github.com/sponsors/XAMPPRocky");
    println!();
    println!("Usage: executable [OPTIONS] [input]...");
    println!();
    println!("Arguments:");
    println!("  [input]...  The path(s) to the file or directory to be counted. (default current directory)");
    println!();
    println!("Options:");
    println!("  -c, --columns <columns>              Sets a strict column width of the output, only available for");
    println!("                                       terminal output.");
    println!("  -e, --exclude <exclude>              Ignore all files & directories matching the pattern.");
    println!("  -f, --files                          Will print out statistics on individual files.");
    println!("  -i, --input <file_input>             Gives statistics from a previous tokei run. Can be given a");
    println!("                                       file path, or \"stdin\" to read from stdin.");
    println!("      --hidden                         Count hidden files.");
    println!("  -l, --languages                      Prints out supported languages and their extensions.");
    println!("      --no-ignore                      Don't respect ignore files (.gitignore, .ignore, etc.). This");
    println!("                                       implies --no-ignore-parent, --no-ignore-dot, and");
    println!("                                       --no-ignore-vcs.");
    println!("      --no-ignore-parent               Don't respect ignore files (.gitignore, .ignore, etc.) in");
    println!("                                       parent directories.");
    println!("      --no-ignore-dot                  Don't respect .ignore and .tokeignore files, including those");
    println!("                                       in parent directories.");
    println!("      --no-ignore-vcs                  Don't respect VCS ignore files (.gitignore, .hgignore, etc.)");
    println!("                                       including those in parent directories.");
    println!("  -o, --output <output>                Outputs Tokei in a specific format. Compile with additional");
    println!("                                       features for more format support.");
    println!("      --streaming <streaming>          prints the (language, path, lines, blanks, code, comments)");
    println!("                                       records as simple lines or as Json for batch processing");
    println!("                                       [possible values: simple, json]");
    println!("  -s, --sort <sort>                    Sort languages based on column [possible values: files,");
    println!("                                       lines, blanks, code, comments]");
    println!("  -r, --rsort <rsort>                  Reverse sort languages based on column [possible values:");
    println!("                                       files, lines, blanks, code, comments]");
    println!("  -t, --types <types>                  Filters output by language type, separated by a comma. i.e.");
    println!("                                       -t=Rust,Markdown");
    println!("  -C, --compact                        Do not print statistics about embedded languages.");
    println!("  -n, --num-format <num_format_style>  Format of printed numbers, i.e., plain (1234, default),");
    println!("                                       commas (1,234), dots (1.234), or underscores (1_234). Cannot");
    println!("                                       be used with --output. [possible values: commas, dots, plain,");
    println!("                                       underscores]");
    println!("  -v, --verbose...                     Set log output level:");
    println!("                                                               1: to show unknown file extensions,");
    println!("                                                               2: reserved for future debugging,");
    println!("                                                               3: enable file level trace. Not");
    println!("                                                               recommended on multiple files");
    println!("  -h, --help                           Print help");
    println!("  -V, --version                        Print version");
}

fn main() {
    let args = parse_args();

    if args.version {
        println!("tokei 14.0.0 compiled with serialization support: json");
        return;
    }

    if args.languages {
        print_languages();
        return;
    }

    let paths = if args.input.is_empty() {
        vec![".".to_string()]
    } else {
        args.input
    };

    let mut results = BTreeMap::new();

    for path_str in paths {
        let path = Path::new(&path_str);
        count_path(path, &mut results);
    }

    if args.output.as_deref() == Some("json") {
        print_json(&results);
    } else if args.files {
        print_table_with_files(&results, args.num_format.as_deref());
    } else {
        print_table(&results, args.num_format.as_deref());
    }
}

fn count_path(path: &Path, results: &mut BTreeMap<String, CountResult>) {
    if path.is_file() {
        if let Some(lang) = language::detect_language(path) {
            let counts = counter::count_file(path);
            results.entry(lang.name().to_string())
                .or_insert_with(|| CountResult::new())
                .merge(counts);
        }
    } else if path.is_dir() {
        count_directory(path, results);
    }
}

fn count_directory(dir: &Path, results: &mut BTreeMap<String, CountResult>) {
    if let Ok(entries) = fs::read_dir(dir) {
        for entry in entries {
            if let Ok(entry) = entry {
                let path = entry.path();
                if path.is_dir() {
                    // Skip hidden and common ignored directories
                    let file_name = path.file_name().unwrap_or_default().to_string_lossy();
                    if file_name.starts_with('.') && file_name != "." {
                        continue;
                    }
                    if file_name == "target" || file_name == "node_modules" {
                        continue;
                    }
                    count_directory(&path, results);
                } else if path.is_file() {
                    if let Some(lang) = language::detect_language(&path) {
                        let counts = counter::count_file(&path);
                        results.entry(lang.name().to_string())
                            .or_insert_with(|| CountResult::new())
                            .merge(counts);
                    }
                }
            }
        }
    }
}

fn print_languages() {
    let langs = language::get_all_languages();
    println!("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━");
    println!("┃ {:36} ┃ {:30} ┃", "Language", "Extensions");
    println!("┃━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┃");
    for lang in langs {
        let exts = lang.extensions().join(", ");
        println!("┃ {:36} ┃ {:30} ┃", lang.name(), exts);
    }
    println!("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━");
}

fn print_table(results: &BTreeMap<String, CountResult>, num_format: Option<&str>) {
    let mut total_lines = 0;
    let mut total_code = 0;
    let mut total_comments = 0;
    let mut total_blanks = 0;
    let mut total_files = 0;

    for (_, result) in results {
        total_files += result.files;
        total_lines += result.lines;
        total_code += result.code;
        total_comments += result.comments;
        total_blanks += result.blanks;
    }

    println!("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━");
    println!(" {:18} {:12} {:13} {:12} {:15} {:12}", 
             "Language", "Files", "Lines", "Code", "Comments", "Blanks");
    println!("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━");

    for (lang, result) in results {
        let fmt = num_format.unwrap_or("plain");
        println!(" {:18} {:12} {:13} {:12} {:15} {:12}",
                 lang,
                 format_number(result.files, fmt),
                 format_number(result.lines, fmt),
                 format_number(result.code, fmt),
                 format_number(result.comments, fmt),
                 format_number(result.blanks, fmt));
    }

    println!("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━");
