                    parsed.exclude.push(args[i].clone());
                }
            }
            "--input" | "-i" => {
                if i + 1 < args.len() {
                    i += 1;
                    parsed.input_file = Some(args[i].clone());
                }
            }
            "--hidden" => {
                parsed.hidden = true;
            }
            "--no-ignore" => {
                parsed.no_ignore = true;
            }
            "--no-ignore-dot" => {
                parsed.no_ignore_dot = true;
            }
            "--no-ignore-parent" => {
                parsed.no_ignore_parent = true;
            }
            "--no-ignore-vcs" => {
                parsed.no_ignore_vcs = true;
            }
            "--output" | "-o" => {
                if i + 1 < args.len() {
                    i += 1;
                    parsed.output = Some(args[i].clone());
                }
            }
            "--sort" | "-s" => {
                if i + 1 < args.len() {
                    i += 1;
                    parsed.sort = Some(args[i].clone());
                }
            }
            "--rsort" | "-r" => {
                if i + 1 < args.len() {
                    i += 1;
                    parsed.rsort = Some(args[i].clone());
                }
            }
            "--types" | "-t" => {
                if i + 1 < args.len() {
                    i += 1;
                    parsed.types = Some(args[i].clone());
                }
            }
            "--compact" | "-C" => {
                parsed.compact = true;
            }
            "--num-format" | "-n" => {
                if i + 1 < args.len() {
                    i += 1;
                    parsed.num_format = Some(args[i].clone());
                }
            }
            "--streaming" => {
                if i + 1 < args.len() {
                    i += 1;
                    parsed.streaming = Some(args[i].clone());
                }
            }
            "--verbose" | "-v" => {
                parsed.verbose += 1;
            }
            "--help" | "-h" => {
                print_help();
                std::process::exit(0);
            }
            arg if arg.starts_with('-') => {
                eprintln!("Unknown option: {}", arg);
            }
            _ => {
                parsed.input.push(args[i].clone());
            }
        }
        i += 1;
    }

    parsed
}

