use std::path::Path;
use std::fs;

#[derive(Clone, Debug)]
pub struct CountResult {
    pub files: usize,
    pub lines: usize,
    pub code: usize,
    pub comments: usize,
    pub blanks: usize,
}

impl CountResult {
    pub fn new() -> Self {
        CountResult {
            files: 0,
            lines: 0,
            code: 0,
            comments: 0,
            blanks: 0,
        }
    }

    pub fn merge(&mut self, other: CountResult) {
        self.files += other.files;
        self.lines += other.lines;
        self.code += other.code;
        self.comments += other.comments;
        self.blanks += other.blanks;
    }
}

pub fn count_file(path: &Path) -> CountResult {
    match fs::read_to_string(path) {
        Ok(content) => count_lines(&content),
        Err(_) => CountResult::new(),
    }
}

fn count_lines(content: &str) -> CountResult {
    let lines: Vec<&str> = content.lines().collect();
    let mut result = CountResult {
        files: 1,
        lines: lines.len(),
        code: 0,
        comments: 0,
        blanks: 0,
    };

    let mut in_block_comment = false;

    for line in &lines {
        let trimmed = line.trim();

        // Check for blank lines
        if trimmed.is_empty() {
            result.blanks += 1;
            continue;
        }

        // Process block comment state at start of line
        let mut has_code = false;
        let mut has_comment = false;
        let mut chars = line.chars().peekable();

        while let Some(ch) = chars.next() {
            // Check for block comment start
            if ch == '/' {
                if let Some(&next) = chars.peek() {
                    if next == '*' {
                        chars.next(); // consume *
                        in_block_comment = true;
                        has_comment = true;
                        continue;
                    } else if next == '/' {
                        // Line comment to end of line
                        has_comment = true;
                        break;
                    }
                }
                has_code = true;
            } else if ch == '#' {
                // Python/Shell comment
                has_comment = true;
                break;
            } else if in_block_comment {
                // We're in a block comment
                if ch == '*' {
                    if let Some(&next) = chars.peek() {
                        if next == '/' {
                            chars.next(); // consume /
                            in_block_comment = false;
                        }
                    }
                }
                has_comment = true;
            } else if !ch.is_whitespace() {
                has_code = true;
            }
        }

        // If we're still in a block comment, this line is a comment line
        if in_block_comment {
            has_comment = true;
        }

        if has_code && has_comment {
            result.code += 1;
            result.comments += 1;
        } else if has_code {
            result.code += 1;
        } else if has_comment {
            result.comments += 1;
        }
    }

    result
}
