            }
        }

        // If we're still in a block comment, this line is a comment line
        if in_block_comment {
            has_comment = true;
        }

        if has_code && has_comment {
            result.code += 1;
            result.comments += 1;
        } else if has_code {
            result.code += 1;
        } else if has_comment {
            result.comments += 1;
        }
    }

