    println!("  -i, --input <file_input>             Gives statistics from a previous tokei run");
    println!("      --hidden                         Count hidden files");
    println!("  -l, --languages                      Prints out supported languages and their extensions");
    println!("      --no-ignore                      Don't respect ignore files");
    println!("      --no-ignore-parent               Don't respect ignore files in parent directories");
    println!("      --no-ignore-dot                  Don't respect .ignore and .tokeignore files");
    println!("      --no-ignore-vcs                  Don't respect VCS ignore files");
    println!("  -o, --output <output>                Outputs Tokei in a specific format");
    println!("      --streaming <streaming>          Print records for batch processing");
    println!("  -s, --sort <sort>                    Sort languages based on column");
    println!("  -r, --rsort <rsort>                  Reverse sort languages based on column");
    println!("  -t, --types <types>                  Filters output by language type");
    println!("  -C, --compact                        Do not print statistics about embedded languages");
    println!("  -n, --num-format <num_format_style>  Format of printed numbers");
    println!("  -v, --verbose...                     Set log output level");
