use std::fs;
use std::path::Path;

mod language;
mod counter;

use counter::CountResult;

#[derive(Debug)]
struct Args {
    input: Vec<String>,
    files: bool,
    languages: bool,
    version: bool,
    output: Option<String>,
    num_format: Option<String>,
}

impl Default for Args {
    fn default() -> Self {
        Args {
            input: Vec::new(),
            files: false,
            languages: false,
            version: false,
            output: None,
            num_format: None,
        }
    }
}

fn parse_args() -> Args {
    let args: Vec<String> = env::args().collect();
    let mut parsed = Args::default();

    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "--version" | "-V" => {
                parsed.version = true;
            }
            "--files" | "-f" => {
                parsed.files = true;
            }
            "--languages" | "-l" => {
                parsed.languages = true;
            }
            "--output" | "-o" => {
                if i + 1 < args.len() {
                    i += 1;
                    parsed.output = Some(args[i].clone());
                }
            }
            "--num-format" | "-n" => {
                if i + 1 < args.len() {
                    i += 1;
                    parsed.num_format = Some(args[i].clone());
                }
            }
            "--help" | "-h" => {
                print_help();
                std::process::exit(0);
            }
            arg if arg.starts_with('-') => {
                // Ignore unknown options for now
            }
            _ => {
                parsed.input.push(args[i].clone());
            }
        }
        i += 1;
    }

    parsed
}

fn print_help() {
    println!("Count your code, quickly.");
    println!("Support this project on GitHub Sponsors: https://github.com/sponsors/XAMPPRocky");
