fn format_number(n: usize, format: &str) -> String {
    match format {
        "commas" => {
            let s = n.to_string();
            let mut result = String::new();
            for (i, c) in s.chars().rev().enumerate() {
                if i > 0 && i % 3 == 0 {
                    result.push(',');
                }
                result.push(c);
            }
            result.chars().rev().collect()
        },
        "dots" => {
            let s = n.to_string();
            let mut result = String::new();
            for (i, c) in s.chars().rev().enumerate() {
                if i > 0 && i % 3 == 0 {
                    result.push('.');
                }
                result.push(c);
            }
            result.chars().rev().collect()
        },
        "underscores" => {
            let s = n.to_string();
            let mut result = String::new();
            for (i, c) in s.chars().rev().enumerate() {
                if i > 0 && i % 3 == 0 {
                    result.push('_');
                }
                result.push(c);
            }
            result.chars().rev().collect()
        },
        _ => n.to_string(),
    }
}

