fn parse_args() -> Args {
    let args: Vec<String> = env::args().collect();
    let mut parsed = Args::default();

    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "--version" | "-V" => {
                parsed.version = true;
            }
            "--files" | "-f" => {
                parsed.files = true;
            }
            "--languages" | "-l" => {
