fn count_path(path: &Path, results: &mut BTreeMap<String, CountResult>) {
    if path.is_file() {
        if let Some(lang) = language::detect_language(path) {
            let counts = counter::count_file(path);
            results.entry(lang.name().to_string())
                .or_insert_with(|| CountResult::new())
                .merge(counts);
        }
    } else if path.is_dir() {
        count_directory(path, results);
    }
}

fn count_directory(dir: &Path, results: &mut BTreeMap<String, CountResult>) {
    if let Ok(entries) = fs::read_dir(dir) {
        for entry in entries {
            if let Ok(entry) = entry {
                let path = entry.path();
                if path.is_dir() {
                    let file_name = path.file_name().unwrap_or_default().to_string_lossy();
                    if file_name.starts_with('.') && file_name != "." {
                        continue;
                    }
                    if file_name == "target" || file_name == "node_modules" {
                        continue;
                    }
                    count_directory(&path, results);
                } else if path.is_file() {
                    if let Some(lang) = language::detect_language(&path) {
                        let counts = counter::count_file(&path);
                        results.entry(lang.name().to_string())
                            .or_insert_with(|| CountResult::new())
                            .merge(counts);
                    }
                }
            }
        }
    }
}

